'use strict';

// MODULES //

var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var factory = require( '@stdlib/ndarray/tensor0d/ctor-factory' );


// MAIN //

/**
* Returns a clamped 8-bit unsigned integer zero-dimensional ndarray.
*
* @name Uint8ClampedTensor0D
* @type {Function}
* @param {(number|ArrayBuffer)} [value] - scalar or buffer
* @param {NonNegativeInteger} [byteOffset=0] - byte offset
* @param {Options} [options] - function options
* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only ndarray
* @param {string} [options.order='row-major'] - memory layout (either row-major or column-major)
* @throws {TypeError} first argument must be either a number, buffer, or options object
* @throws {TypeError} must provide valid options
* @returns {ndarray} zero-dimensional ndarray
*
* @example
* var arr = new Uint8ClampedTensor0D();
* // returns <ndarray>[ 0 ]
*
* @example
* var arr = new Uint8ClampedTensor0D( 1 );
* // returns <ndarray>[ 1 ]
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 1 );
* var arr = new Uint8ClampedTensor0D( buf );
* // returns <ndarray>[ 0 ]
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 9 );
* var arr = new Uint8ClampedTensor0D( buf, 8 );
* // returns <ndarray>[ 0 ]
*/
var Uint8ClampedTensor0D = factory( 'uint8c', 0, isNumber );


// EXPORTS //

module.exports = Uint8ClampedTensor0D;
